import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Mail, Lock } from 'lucide-react';
import { login as apiLogin } from '../services/api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await apiLogin(form);
      login(res.data.token, res.data.user);
      toast.success('Bienvenue !');
      navigate('/dashboard');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Identifiants incorrects');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-gradient-to-br from-green-800 via-green-900 to-slate-900">
      {/* Left decorative panel */}
      <div className="hidden lg:flex w-1/2 flex-col items-center justify-center text-white relative overflow-hidden">

  {/* circles background */}
  <div className="absolute w-[500px] h-[500px] bg-green-500/20 rounded-full blur-3xl animate-pulse"></div>
  <div className="absolute w-[300px] h-[300px] bg-emerald-400/20 rounded-full blur-2xl top-20 right-10"></div>

  <div className="relative z-10 text-center space-y-6">
    <div className="w-20 h-20 bg-white/20 backdrop-blur rounded-2xl flex items-center justify-center mx-auto">
      <span className="text-2xl font-bold">OCP</span>
    </div>

    <h1 className="text-4xl font-bold">Gestion du Stock</h1>
    <p className="text-green-100 max-w-md">
      Plateforme intelligente pour gérer vos équipements électriques en temps réel
    </p>

    <div className="flex gap-4 mt-6">
      {['Articles','Transferts','Alertes'].map((item,i)=>(
        <div key={i} className="px-4 py-3 bg-white/10 backdrop-blur rounded-xl text-sm">
          {item}
        </div>
      ))}
    </div>
  </div>
</div>

      {/* Right login form */}
    <div className="flex w-full lg:w-1/2 items-center justify-center bg-white">

  <div className="w-full max-w-md p-8 space-y-6">

    <div>
      <h2 className="text-2xl font-bold text-gray-800">Bienvenue 👋</h2>
      <p className="text-gray-500 text-sm">Connectez-vous à votre compte</p>
    </div>

    {/* INPUT EMAIL */}
    <div className="space-y-2">
      <label className="text-xs text-gray-500">Email</label>
      <input 
        type="email"
        className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-green-500 outline-none transition"
        placeholder="admin@ocp.ma"
      />
    </div>

    {/* INPUT PASSWORD */}
    <div className="space-y-2">
      <label className="text-xs text-gray-500">Mot de passe</label>
      <input 
        type="password"
        className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-green-500 outline-none transition"
        placeholder="••••••••"
      />
    </div>

    {/* BUTTON */}
    <button className="w-full py-3 bg-green-600 text-white rounded-xl font-semibold hover:bg-green-700 transition shadow-lg hover:shadow-xl">
      Se connecter
    </button>

  </div>
</div>
    </div>
  );
}
